<?php

namespace PasBundle\Repository;

/**
 * PasRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class PasRepository extends \Doctrine\ORM\EntityRepository {

    public function bilan() {
        $qb = $this->getEntityManager()->createQueryBuilder()
                ->select('sum(n.note) as note, sum(ac.criterenote) as surnote,(sum(n.note)/sum(ac.criterenote)) as moy, p')
                ->from('PasBundle:Pas', 'p')
                ->innerJoin('p.axes', 'ax')
                ->innerJoin('ax.objectifs', 'ob')
                ->innerJoin('ob.actions', 'ac')
                ->innerJoin('ac.notes', 'n')
                ->groupBy('p')
                ->orderBy('moy','DESC')
        ;

        return $qb->getQuery()->getResult();
    }

}
